var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`CINDY_VATICAN_HALLOWEEN_NULL`,text:{KOREA:`이 계약은 성 요셉의 가호 아래 체결됐어. 이제부터 우리 사이에 배신은 없다는 뜻이지. 성인님 체면도 있으니까 잘 지켜 줘야 돼?`,JPN:`この契約は聖ヨセフの加護の元で結ばれたんだ。これからアタシたちの間に裏切りは無しってこと。聖人様のメンツもあるから、ちゃんと守るんだぞ？`,ENG:`Our contract has been concluded with a blessing from Saint Joseph, meaning there should be no betrayal between us. You'd better not disappoint the Saint.`,TWN:`這份契約是在聖約翰的加護下締結的，代表之後我們之間再也沒有背叛。看在聖人的面上，你可不能反悔喔？`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`CINDY_VATICAN_HALLOWEEN_NULL`,face:`UNIT_PRIDE`,hologram:!1},R:null}}}];export{e as default};